SELECT carrier, cost_bucket, kerry_count, total_cost FROM (SELECT carrier, CASE WHEN cost >= 79 THEN 'high' WHEN cost >= 32 THEN 'mid' ELSE 'low' END AS cost_bucket, SUM(CASE WHEN carrier = 'Kerry' THEN 1 ELSE 0 END) AS kerry_count, SUM(cost) AS total_cost FROM shipments WHERE order_id IS NOT NULL GROUP BY carrier, CASE WHEN cost >= 79 THEN 'high' WHEN cost >= 32 THEN 'mid' ELSE 'low' END) AS sub WHERE total_cost < 560;
